1916	fn main() {
1917	    // `ax desktop` must run on the OS main thread — winit panics on Windows if
1918	    // EventLoop is created from the ax-main worker (see EventLoopBuilderExtWindows).
1919	    if std::env::args().nth(1).as_deref() == Some("desktop") {
1920	        run_desktop_on_os_main_thread();
1921	        return;
1922	    }
1923	
1924	    // Windows main threads get 1 MB of stack; the combined command future is
1925	    // large enough to overflow it in unoptimized builds. Run everything on a
1926	    // worker thread with a roomier stack instead.
1927	    let child = std::thread::Builder::new()
1928	        .name("ax-main".into())
1929	        .stack_size(16 * 1024 * 1024)
1930	        .spawn(|| {
1931	            let runtime = tokio::runtime::Builder::new_multi_thread()
1932	                .enable_all()
1933	                .thread_stack_size(16 * 1024 * 1024)
1934	                .build()
1935	                .expect("failed to build tokio runtime");
1936	            runtime.block_on(async_main());
1937	        })
1938	        .expect("failed to spawn main thread");
1939	    if child.join().is_err() {
1940	        std::process::exit(1);
1941	    }
1942	}

